a:arguments.a:argument:
var LOOKUP = "https://maelkolb.github.io/humboldt-hand-lookup/";
var YEARS = "string-join(for $date in (//*:correspAction[@type = 'sent']/*:date, //*:profileDesc/*:creation/*:date)[1]," +
  " $from in substring(($date/@when, $date/@notBefore, $date/@from, $date/@notAfter, $date/@to)[1], 1, 4)," +
  " $to in substring(($date/@when, $date/@notAfter, $date/@to, $date/@notBefore, $date/@from)[1], 1, 4)" +
  " return if (number($from) = number($from) and number($to) = number($to))" +
  " then concat(number($from) - 5, '-', number($to) + 5) else '', '')";

function selection() {
  var text = authorAccess.getEditorAccess().getSelectedText();
  return text == null ? "" : String(text).replace(/\s+/g, " ").replace(/^ | $/g, "");
}

function years() {
  try {
    var found = authorAccess.getDocumentController().evaluateXPath(YEARS, false, false, false);
    return found != null && found.length ? String(found[0]) : "";
  } catch (e) {
    return "";
  }
}

function open(url) {
  Packages.java.awt.Desktop.getDesktop().browse(new Packages.java.net.URI(url));
}

function doOperation() {
  var text = selection();
  if (!text) {
    authorAccess.getWorkspaceAccess().showInformationMessage("Select a word first.");
    return;
  }
  var range = years();
  open(LOOKUP + "#q=" + encodeURIComponent(text) + (range ? "&y=" + range : ""));
}
